arguments.command:
cat << 'EOF' > /tmp/bconv.sh
#!/bin/bash
echo -e "══ QUICK UNIT CONVERTER ══\r\n1) Celsius to Fahrenheit\r\n2) Kilometers to Miles\r\n3) Kilograms to Pounds\r"
read -p "Choose option (1-3): " opt
read -p "Enter value to convert: " val
if ! [[ "$val" =~ ^[0-9.]+$ ]]; then echo -e "Invalid number!\r"; exit 1; fi
case "$opt" in
  1) res=$(echo "scale=2; ($val * 9/5) + 32" | bc); echo -e "$val °C = $res °F\r" ;;
  2) res=$(echo "scale=2; $val * 0.621371" | bc); echo -e "$val Km = $res Miles\r" ;;
  3) res=$(echo "scale=2; $val * 2.20462" | bc); echo -e "$val Kg = $res Lbs\r" ;;
  *) echo -e "Invalid option\r" ;;
esac
EOF
tput cuu 1 && termy_say "Opening unit converter" > /dev/null 2>&1 && printf "\r\n" && bash /tmp/bconv.sh; rm -f /tmp/bconv.sh && printf ""

printf 'print("══ PRIME NUMBER CHECKER ══")
while True:
    n=input("Number (q to quit): ")
    if n=="q":
        break
    if not n.isdigit():
        print("Enter a positive integer!")
        continue
    v=int(n)
    if v<2:
        ok=False
    elif v==2:
        ok=True
    elif v & 1 == 0:
        ok=False
    else:
        i=3
        ok=True
        while i*i<=v:
            if (v//i)*i==v:
                ok=False
                break
            i+=2
    print(n + (" IS prime ✓" if ok else " is NOT prime ✗"))
' > /tmp/prime.py && python3 /tmp/prime.py; rm -f /tmp/prime.py && termy_say "Closing prime checker" > /dev/null 2>&1

printf 'import math
print("══ FACTORIAL / PERMUTATIONS / COMBINATIONS ══")
print("1) n!  2) nPk permutations  3) nCk combinations")
opt=input("Choose (1-3): ")
try:
    n=int(input("n = "))
    k=0
    if opt!="1":
        k=int(input("k = "))
except ValueError:
    print("Integers only!")
    raise SystemExit
if n<0 or k<0:
    print("Negative values not allowed")
elif opt=="1":
    print(str(n) + "! = " + str(math.factorial(n)))
elif opt not in ("2","3"):
    print("Invalid option")
elif k>n:
    print("k must be <= n (cannot choose " + str(k) + " items from " + str(n) + ")")
elif opt=="2":
    print("P(" + str(n) + "," + str(k) + ") = " + str(math.factorial(n)//math.factorial(n-k)))
else:
    print("C(" + str(n) + "," + str(k) + ") = " + str(math.factorial(n)//(math.factorial(k)*math.factorial(n-k))))
' > /tmp/fact.py && python3 /tmp/fact.py; rm -f /tmp/fact.py && termy_say "Closing factorial calculator" > /dev/null 2>&1

printf 'print("══ PERCENTAGE CALCULATOR ══")
print("1) X percent of N")
print("2) X is what percent of N")
print("3) Percent change from A to B")
print("4) Apply X percent discount to N")
opt=input("Choose (1-4): ")
try:
    a=float(input("First value: "))
    b=float(input("Second value: "))
except ValueError:
    print("Numbers only!")
    raise SystemExit
if opt=="1":
    print(str(a) + " percent of " + str(b) + " = " + str(round(a*b/100,4)))
elif opt=="2":
    if b==0:
        print("Cannot divide by zero")
    else:
        print(str(a) + " is " + str(round(a/b*100,4)) + " percent of " + str(b))
elif opt=="3":
    if a==0:
        print("Cannot divide by zero")
    else:
        print("Change from " + str(a) + " to " + str(b) + " = " + str(round((b-a)/a*100,4)) + " percent")
elif opt=="4":
    print(str(b) + " with " + str(a) + " percent discount = " + str(round(b*(1-a/100),4)))
else:
    print("Invalid option")
' > /tmp/pct.py && python3 /tmp/pct.py; rm -f /tmp/pct.py && termy_say "Closing percentage calculator" > /dev/null 2>&1

printf 'print("══ NUMBER BASE CONVERTER ══")
print("Accepts 0x hex, 0b binary, 0o octal, plain decimal")
print("Tip: 0/1-only strings are also read as binary")
while True:
    n=input("Number (q to quit): ").strip()
    if n=="q":
        break
    v=None
    try:
        v=int(n,0)
    except ValueError:
        pass
    if v is None and n and all(c in "01" for c in n):
        v=int(n,2)
    if v is None:
        print("Invalid number format!")
    else:
        print("DEC: " + str(v) + "   HEX: " + hex(v)[2:].upper() + "   OCT: " + oct(v)[2:] + "   BIN: " + bin(v)[2:])
' > /tmp/base.py && python3 /tmp/base.py; rm -f /tmp/base.py && termy_say "Closing base converter" > /dev/null 2>&1

printf 'print("══ POWERS & ROOTS ══")
while True:
    line=input("base exponent (q to quit): ")
    if line=="q":
        break
    parts=line.split()
    if len(parts)!=2:
        print("Enter base and exponent separated by space!")
        continue
    try:
        b=float(parts[0])
        e=float(parts[1])
    except ValueError:
        print("Numbers only!")
        continue
    p=b**e
    print(str(b) + " ^ " + str(e) + " = " + str(round(p,6)))
    if e!=0 and p>0:
        print("   " + str(e) + "-th root of " + str(round(p,6)) + " = " + str(round(p**(1/e),6)))
' > /tmp/pow.py && python3 /tmp/pow.py; rm -f /tmp/pow.py && termy_say "Closing powers and roots calculator" > /dev/null 2>&1
